// reader.cpp
// Attach to a target process, read a view matrix and entity list from known
// offsets, and emit one JSON object per tick to stdout.
//
// Build (MSVC):
//   cl /std:c++17 /O2 /W4 /DUNICODE reader.cpp /link /out:reader.exe
//
// Build with smoke-test entry point:
//   cl /std:c++17 /O2 /W4 /DUNICODE /DSMOKE_MAIN reader.cpp /link /out:reader.exe
//
// Adjust BASE_ADDR, VM_OFFSET, ENTITY_LIST_OFFSET, MAX_ENTITIES, and
// TICK_MS to match the target process's memory layout.

#include <windows.h>
#include <tlhelp32.h>
#include <psapi.h>
#include <cstdio>
#include <cstdint>
#include <cstring>
#include <string>
#include <array>
#include <vector>
#include <chrono>
#include <thread>

// ---------------------------------------------------------------------------
// Configuration – tune these for your target
// ---------------------------------------------------------------------------
static constexpr wchar_t  TARGET_EXE[]          = L"game.exe";
static constexpr uintptr_t VM_OFFSET             = 0x00ABC123; // offset from module base to view-matrix ptr
static constexpr uintptr_t ENTITY_LIST_OFFSET    = 0x00DEF456; // offset from module base to entity-list ptr
static constexpr int       MAX_ENTITIES          = 64;
static constexpr DWORD     TICK_MS               = 16;         // ~60 Hz

// ---------------------------------------------------------------------------
// Data layout expected in the target's memory
// ---------------------------------------------------------------------------
#pragma pack(push, 1)
struct ViewMatrix {
    float m[4][4];
};

struct EntityEntry {
    uint8_t  valid;        // non-zero when slot is occupied
    uint8_t  team;
    uint8_t  _pad[2];
    int32_t  id;
    float    pos[3];       // world-space XYZ
    float    angles[3];    // pitch, yaw, roll
    int32_t  health;
    int32_t  armor;
    char     name[32];
};
#pragma pack(pop)

// ---------------------------------------------------------------------------
// Process / module helpers
// ---------------------------------------------------------------------------
static DWORD FindProcessId(const wchar_t* exeName)
{
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snap == INVALID_HANDLE_VALUE) return 0;

    PROCESSENTRY32W pe{};
    pe.dwSize = sizeof(pe);
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, exeName) == 0) {
                pid = pe.th32ProcessID;
                break;
            }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

static uintptr_t GetModuleBase(HANDLE hProcess, const wchar_t* modName)
{
    HMODULE mods[1024];
    DWORD   needed = 0;
    if (!EnumProcessModulesEx(hProcess, mods, sizeof(mods), &needed,
                               LIST_MODULES_ALL))
        return 0;

    const DWORD count = needed / sizeof(HMODULE);
    wchar_t name[MAX_PATH];
    for (DWORD i = 0; i < count; ++i) {
        if (GetModuleFileNameExW(hProcess, mods[i], name, MAX_PATH)) {
            // compare the filename part only
            const wchar_t* slash = wcsrchr(name, L'\\');
            const wchar_t* file  = slash ? slash + 1 : name;
            if (_wcsicmp(file, modName) == 0)
                return reinterpret_cast<uintptr_t>(mods[i]);
        }
    }
    return 0;
}

// Safe RPM wrapper – returns false on partial read
static bool RPM(HANDLE hProcess, uintptr_t addr, void* buf, SIZE_T sz)
{
    SIZE_T read = 0;
    if (!ReadProcessMemory(hProcess,
                           reinterpret_cast<LPCVOID>(addr),
                           buf, sz, &read))
        return false;
    return read == sz;
}

// Follow a pointer chain: read a pointer at base+offset, then read sz bytes
// from that pointer into buf.
static bool ReadViaPointer(HANDLE    hProcess,
                            uintptr_t base,
                            uintptr_t offset,
                            void*     buf,
                            SIZE_T    sz)
{
    uintptr_t ptr = 0;
    if (!RPM(hProcess, base + offset, &ptr, sizeof(ptr))) return false;
    if (!ptr) return false;
    return RPM(hProcess, ptr, buf, sz);
}

// ---------------------------------------------------------------------------
// JSON serialisation (no external library)
// ---------------------------------------------------------------------------
static std::string EscapeJsonString(const char* s)
{
    std::string out;
    out.reserve(64);
    for (; *s; ++s) {
        unsigned char c = static_cast<unsigned char>(*s);
        if      (c == '"')  { out += "\\\""; }
        else if (c == '\\') { out += "\\\\"; }
        else if (c == '\n') { out += "\\n";  }
        else if (c == '\r') { out += "\\r";  }
        else if (c == '\t') { out += "\\t";  }
        else if (c < 0x20)  { char esc[8]; snprintf(esc, sizeof(esc), "\\u%04x", c); out += esc; }
        else                 { out += static_cast<char>(c); }
    }
    return out;
}

static std::string FormatTick(uint64_t            tick,
                               const ViewMatrix&   vm,
                               const std::vector<EntityEntry>& ents)
{
    char buf[256];
    std::string out;
    out.reserve(4096);

    snprintf(buf, sizeof(buf), "{\"tick\":%llu,\"view_matrix\":[", (unsigned long long)tick);
    out += buf;

    for (int r = 0; r < 4; ++r)
        for (int c = 0; c < 4; ++c) {
            snprintf(buf, sizeof(buf), "%.6f", vm.m[r][c]);
            out += buf;
            if (r < 3 || c < 3) out += ',';
        }

    out += "],\"entities\":[";
    bool first = true;
    for (const auto& e : ents) {
        if (!e.valid) continue;
        if (!first) out += ',';
        first = false;

        char name[64];
        // ensure null-termination before escaping
        strncpy_s(name, sizeof(name), e.name, _TRUNCATE);

        snprintf(buf, sizeof(buf),
            "{\"id\":%d,\"team\":%d,"
            "\"pos\":[%.3f,%.3f,%.3f],"
            "\"angles\":[%.3f,%.3f,%.3f],"
            "\"health\":%d,\"armor\":%d,"
            "\"name\":\"",
            e.id, e.team,
            e.pos[0], e.pos[1], e.pos[2],
            e.angles[0], e.angles[1], e.angles[2],
            e.health, e.armor);
        out += buf;
        out += EscapeJsonString(name);
        out += "\"}";
    }
    out += "]}\n";
    return out;
}

// ---------------------------------------------------------------------------
// Reader loop
// ---------------------------------------------------------------------------
static int ReaderLoop(HANDLE hProcess, uintptr_t moduleBase)
{
    uint64_t tick = 0;

    for (;;) {
        const auto frameStart = std::chrono::steady_clock::now();

        // --- view matrix ---
        ViewMatrix vm{};
        if (!ReadViaPointer(hProcess, moduleBase, VM_OFFSET, &vm, sizeof(vm))) {
            // pointer invalid this frame; emit zeros and continue
            memset(&vm, 0, sizeof(vm));
        }

        // --- entity list ---
        uintptr_t listPtr = 0;
        std::vector<EntityEntry> ents;
        ents.resize(MAX_ENTITIES);

        bool listOk = RPM(hProcess, moduleBase + ENTITY_LIST_OFFSET,
                          &listPtr, sizeof(listPtr))
                      && listPtr != 0
                      && RPM(hProcess, listPtr,
                             ents.data(),
                             sizeof(EntityEntry) * MAX_ENTITIES);
        if (!listOk) ents.assign(MAX_ENTITIES, EntityEntry{});

        // --- emit JSON ---
        const std::string json = FormatTick(tick++, vm, ents);
        fwrite(json.c_str(), 1, json.size(), stdout);
        fflush(stdout);

        // --- throttle to tick rate ---
        const auto elapsed = std::chrono::steady_clock::now() - frameStart;
        const auto budget  = std::chrono::milliseconds(TICK_MS);
        if (elapsed < budget)
            std::this_thread::sleep_for(budget - elapsed);

        // --- check process still alive ---
        DWORD exitCode = 0;
        if (!GetExitCodeProcess(hProcess, &exitCode) ||
             exitCode != STILL_ACTIVE)
            break;
    }

    return 0;
}

// ---------------------------------------------------------------------------
// Entry point (normal use)
// ---------------------------------------------------------------------------
#ifndef SMOKE_MAIN

int wmain(int argc, wchar_t* argv[])
{
    const wchar_t* target = (argc >= 2) ? argv[1] : TARGET_EXE;

    const DWORD pid = FindProcessId(target);
    if (!pid) {
        fprintf(stderr, "reader: process '%ls' not found\n", target);
        return 1;
    }

    HANDLE hProcess = OpenProcess(
        PROCESS_VM_READ | PROCESS_QUERY_INFORMATION,
        FALSE, pid);
    if (!hProcess) {
        fprintf(stderr, "reader: OpenProcess failed (%lu)\n", GetLastError());
        return 1;
    }

    const uintptr_t base = GetModuleBase(hProcess, target);
    if (!base) {
        fprintf(stderr, "reader: could not find module base for '%ls'\n", target);
        CloseHandle(hProcess);
        return 1;
    }

    fprintf(stderr, "reader: attached pid=%lu base=0x%llx\n",
            pid, (unsigned long long)base);

    const int rc = ReaderLoop(hProcess, base);
    CloseHandle(hProcess);
    return rc;
}

#else // SMOKE_MAIN

// ---------------------------------------------------------------------------
// Smoke test – exercises helpers without attaching to any real process
// ---------------------------------------------------------------------------
static void SmokeTest()
{
    // JSON formatter test
    ViewMatrix vm{};
    for (int r = 0; r < 4; ++r)
        for (int c = 0; c < 4; ++c)
            vm.m[r][c] = (r == c) ? 1.0f : 0.0f; // identity matrix

    std::vector<EntityEntry> ents(2);
    ents[0].valid  = 1;
    ents[0].id     = 1;
    ents[0].team   = 2;
    ents[0].health = 100;
    ents[0].armor  = 50;
    ents[0].pos[0] = 128.5f; ents[0].pos[1] = 0.0f; ents[0].pos[2] = 64.0f;
    strncpy_s(ents[0].name, sizeof(ents[0].name), "Player\"One\\", _TRUNCATE);

    ents[1].valid  = 0; // should be omitted

    const std::string json = FormatTick(0, vm, ents);
    fputs(json.c_str(), stdout);

    // FindProcessId / GetModuleBase with a known process
    const DWORD selfPid = GetCurrentProcessId();
    HANDLE hSelf = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION,
                                FALSE, selfPid);
    if (hSelf) {
        wchar_t selfExe[MAX_PATH]{};
        GetModuleFileNameExW(hSelf, nullptr, selfExe, MAX_PATH);
        const wchar_t* slash = wcsrchr(selfExe, L'\\');
        const wchar_t* name  = slash ? slash + 1 : selfExe;
        const uintptr_t base = GetModuleBase(hSelf, name);
        fprintf(stderr, "smoke: self pid=%lu exe=%ls base=0x%llx\n",
                selfPid, name, (unsigned long long)base);
        CloseHandle(hSelf);
    }

    fputs("smoke: OK\n", stderr);
}

int wmain(int /*argc*/, wchar_t** /*argv*/)
{
    SmokeTest();
    return 0;
}

#endif // SMOKE_MAIN
